INSERT INTO public.version_legal VALUES (1, 1, 'terminos', 1, 0, 'Estos términos regulan el uso de la plataforma AgeCare por parte de familiares, cuidadoras, médicos y adultos mayores. El servicio entrega información de apoyo al cuidado y no reemplaza la atención médica. Estos términos regulan el uso de la plataforma AgeCare por parte de familiares, cuidadoras, médicos y adultos mayores. El servicio entrega información de apoyo al cuidado y no reemplaza la atención médica. Estos términos regulan el uso de la plataforma AgeCare por parte de familiares, cuidadoras, médicos y adultos mayores. El servicio entrega información de apoyo al cuidado y no reemplaza la atención médica. ', 'Versión inicial para la publicación en tiendas.', '2026-08-01', true, 'publicada', '2026-08-26 03:14:53.127329+00');
INSERT INTO public.version_legal VALUES (2, 1, 'privacidad', 1, 0, 'AgeCare trata datos de salud con el consentimiento del titular o de su representante, solo para entregar el servicio de cuidado. Los datos se almacenan cifrados y no se venden a terceros. AgeCare trata datos de salud con el consentimiento del titular o de su representante, solo para entregar el servicio de cuidado. Los datos se almacenan cifrados y no se venden a terceros. AgeCare trata datos de salud con el consentimiento del titular o de su representante, solo para entregar el servicio de cuidado. Los datos se almacenan cifrados y no se venden a terceros. ', 'Versión inicial conforme a la Ley 19.628.', '2026-08-01', true, 'publicada', '2026-08-26 03:14:53.127329+00');
