INSERT INTO public.contenido VALUES (1, 'chiste', '¿Qué le dijo el café al azúcar?', 'Sin ti mi vida es amarga. Y con leche, un poco más tranquila.', 'humor', 'publicado', NULL, '2026-10-25 03:14:53.127329+00', '2026-10-23 03:14:53.127329+00', NULL, NULL, NULL);
INSERT INTO public.contenido VALUES (2, 'chiste', 'El reloj', '¿Por qué el reloj fue al médico? Porque tenía las manecillas atrasadas.', 'humor', 'publicado', NULL, '2026-10-26 03:14:53.127329+00', '2026-10-24 03:14:53.127329+00', NULL, NULL, NULL);
INSERT INTO public.contenido VALUES (3, 'chiste', 'La planta', '¿Qué le dijo una planta a otra? ¡Qué gusto verte tan florecida esta mañana!', 'humor', 'publicado', NULL, '2026-10-27 03:14:53.127329+00', '2026-10-25 03:14:53.127329+00', NULL, NULL, NULL);
INSERT INTO public.contenido VALUES (4, 'chiste', 'El pan', '¿Por qué el pan no habla? Porque está en la luna de miel… con la mantequilla.', 'humor', 'borrador', NULL, NULL, '2026-10-26 03:14:53.127329+00', NULL, NULL, NULL);
INSERT INTO public.contenido VALUES (5, 'noticia', 'Coro de adultos mayores gana premio regional', 'El coro «Voces de Ñuñoa» obtuvo el primer lugar en el festival regional de música.', 'comunidad,actualidad', 'publicado', NULL, '2026-10-31 03:14:53.127329+00', '2026-10-29 03:14:53.127329+00', NULL, NULL, NULL);
