INSERT INTO public.contenido VALUES (8, 'noticia', 'Taller gratuito de memoria en bibliotecas', 'Las bibliotecas municipales abren talleres de estimulación cognitiva los martes.', 'comunidad,actualidad', 'borrador', NULL, NULL, '2026-11-01 03:14:53.127329+00', NULL, NULL, NULL);
